                 && unit_ready && kv_gate && w_gate;

    // ---- DEC_LA_ISSUE_FB (tools/qwen_rom_core_issue_fallback_w12.py) ---------------------------------------
    wire fb_kvg_me = (KV_HBM == 0) || !me_wsrc || (kv_ok_i && !kvd_v);
    wire fb_wg_me = (W_HBM == 0) || me_wsrc || (w_ok && !wd_v);
    wire fb_wg_su = (W_HBM == 0) || !a_src || emb_ok;
    wire fb_rdy_su = su_ready && (!KV_VEC_WRITE_BRIDGE || (su_idle && kv_write_drained_i));
    wire fb_waits = (!d_wait_me || me_idle) && (!d_wait_su || su_idle);
    wire fb_cond_me, fb_cond_su, fb_is_me, fb_is_su, fb_is_s3;
    wire fb_load;                                   // = load (declared below)
    generate if (DEC_LA_ISSUE_FB >= 2) begin : g_fb_oh
        // one-hot selection, registered with d_unit / d_barrier / d_chase / d_chase_rows (same LOAD edge)
        reg oh_me, oh_su, oh_s3, oh_bar, oh_me_rows, oh_me_prog, oh_su_chase;
        always @(posedge clk) if (fb_load) begin
            oh_me <= fqd_d_unit[la_rd] == 2'd1;
            oh_su <= fqd_d_unit[la_rd] == 2'd2;
            oh_s3 <= fqd_d_unit[la_rd] == 2'd3;
            oh_bar <= fqd_d_barrier[la_rd];
            oh_me_rows <= fqd_d_unit[la_rd] == 2'd1 && fqd_d_chase[la_rd] && fqd_d_chase_rows[la_rd];
            oh_me_prog <= fqd_d_unit[la_rd] == 2'd1 && fqd_d_chase[la_rd] && !fqd_d_chase_rows[la_rd];
            oh_su_chase <= fqd_d_unit[la_rd] != 2'd1 && fqd_d_chase[la_rd];
        end
        assign fb_is_me = oh_me; assign fb_is_su = oh_su; assign fb_is_s3 = oh_s3;
        assign fb_cond_me = oh_bar ? drained
                                   : ((!oh_me_rows || ge_su_rows) && (!oh_me_prog || ge_su_prog) && fb_waits);
        assign fb_cond_su = oh_bar ? drained : ((!oh_su_chase || ge_me_prog) && fb_waits);
    end else begin : g_fb_mux
        assign fb_is_me = d_unit == 2'd1; assign fb_is_su = d_unit == 2'd2; assign fb_is_s3 = d_unit == 2'd3;
        assign fb_cond_me = d_barrier ? drained
                                      : ((!d_chase || (d_chase_rows ? ge_su_rows : ge_su_prog)) && fb_waits);
        assign fb_cond_su = d_barrier ? drained : ((!d_chase || ge_me_prog) && fb_waits);
    end endgenerate
    wire fb_run = (st == S_RUN) && nx_v;
    (* keep *) wire fb_me_go = fb_run && fb_is_me && fb_cond_me && me_ready && me_en && fb_kvg_me && fb_wg_me;
    (* keep *) wire fb_am_go = fb_run && fb_is_me && fb_cond_me && me_ready && me_en && fb_kvg_me && fb_wg_me;
    (* keep *) wire fb_su_go = fb_run && fb_is_su && fb_cond_su && fb_rdy_su && fb_wg_su;
    (* keep *) wire fb_s3_go = fb_run && fb_is_s3 && fb_cond_su && fb_rdy_su && fb_wg_su;
    wire issue_ld = (DEC_LA_ISSUE_FB != 0) ? (fb_me_go || fb_su_go || fb_s3_go) : issue;
    assign me_go = (DEC_LA_ISSUE_FB != 0) ? fb_me_go : (issue && (d_unit == 2'd1));
    (* keep *) wire la_issue_am = (st == S_RUN) && nx_v && (d_unit != 2'd0) &&
                 (d_barrier ? drained : ((!d_chase || chased) && (!d_wait_me || me_idle) && (!d_wait_su || su_idle)))
                 && unit_ready && kv_gate && w_gate;
    wire la_me_go_am = (DEC_LA_ISSUE_FB != 0) ? fb_am_go
                     : (DEC_LA != 0) ? (la_issue_am && (d_unit == 2'd1)) : me_go;
    assign su_go = (DEC_LA_ISSUE_FB != 0) ? fb_su_go : (issue && (d_unit == 2'd2));
    reg fin_d;
    wire fin = (st == S_RUN) && nx_v && (d_unit == 2'd0) && drained;
    //: decode the FIFO head into NEXT when NEXT is empty or issuing
    // Separate LOAD removes the issue/ready cone from all NEXT captures.
    wire load = (st == S_RUN) && (fq_n != 0) &&
                (!nx_v || ((DEC_LA_SEPARATE_LOAD == 0) && issue_ld));
    assign fb_load = load;
    wire push = (st == S_RUN) && pend1;
    wire [2:0] la_fqn_nl = fq_n + (push ? 3'd1 : 3'd0);      // DEC_LA: fq_n without / with a LOAD
    wire [2:0] la_fqn_l  = fq_n + (push ? 3'd0 : 3'd7);

    // DEC_LA_ISSUE_FB >= 3: token_i and position are captured on every idle edge (the start_i edge included)
    always @(posedge clk) if (st == S_IDLE && (DEC_LA_ISSUE_FB >= 3 || (rst_n_i && start_i))) begin
        tok_r <= token_i; pos_r <= pos_i;
    end
    wire [31:0] la_cycles1;
    ot_hdc_inc_k #(.W(32)) u_la_cycles (.a(cycles), .inc(1'b1), .y(la_cycles1), .co());
    always @(posedge clk or negedge rst_n_i) begin
        if (!rst_n_i) begin
            st <= S_IDLE; pc <= 0; fpc <= 0; done <= 1'b0; prog_re <= 1'b0; pend1 <= 1'b0; pend0 <= 1'b0;
            fq_rd <= 0; fq_wr <= 0; fq_n <= 0; nx_v <= 1'b0;
            cycles <= 0; next_token <= 0; fin_d <= 1'b0;
        end else begin
            if (DEC_LA_PINREG != 0) done <= 1'b0; // registered completion pulse
            if (st != S_IDLE) cycles <= (DEC_LA != 0) ? la_cycles1 : cycles + 1;
            pend0 <= prog_re && (st != S_IDLE);
            pend1 <= (DEC_LA_PINREG == 0 || DEC_LA_PINREG == 3) ? (prog_re && (st != S_IDLE))
                                                              : (pend0 && (st != S_IDLE));
            prog_re <= 1'b0;
            case (st)
                S_IDLE: if (start_i) begin
                    pc <= 0; fpc <= 0; done <= 1'b0; cycles <= 0;
                    fq_rd <= 0; fq_wr <= 0; fq_n <= 0; nx_v <= 1'b0; pend1 <= 1'b0; pend0 <= 1'b0;
                    st <= S_DYN;
                end
                S_DYN: st <= S_RUN;
                S_RUN: begin
                    // fetch: one word a cycle while fewer than NFQ are held or in flight
                    if ({1'b0, fq_n} + prog_re + pend1 + ((DEC_LA_PINREG == 1 || DEC_LA_PINREG == 2) ? pend0 : 1'b0) < NFQ) begin
                        prog_re <= 1'b1; prog_addr <= fpc; fpc <= fpc + 1'b1;
                    end
                    if (push) begin fq[fq_wr] <= prog_q_i; fq_wr <= fq_wr + 1'b1; end
                    if (load) fq_rd <= fq_rd + 1'b1;
                    fq_n <= (DEC_LA != 0) ? (load ? la_fqn_l : la_fqn_nl)
                                          : fq_n + (push ? 3'd1 : 3'd0) - (load ? 3'd1 : 3'd0);
                    if (issue_ld) pc <= pc + 1'b1;
                    if (load) nx_v <= 1'b1;
                    else if (issue_ld) nx_v <= 1'b0;
                    if (fin) begin
                        if (DEC_LA_AMQ == 0) begin done <= 1'b1; next_token <= fin_idx; end
                        st <= S_IDLE; nx_v <= 1'b0;
                        prog_re <= 1'b0;
                    end
                end
                default: st <= S_IDLE;
            endcase
            fin_d <= (DEC_LA_AMQ != 0) && fin;
            if (DEC_LA_AMQ != 0 && fin_d) begin done <= 1'b1; next_token <= fin_idx; end
        end
    end

    always @(posedge clk or negedge rst_n_i) begin
        if (!rst_n_i) begin kvd_v <= 1'b0; wd_v <= 1'b0; end
        else begin
            kvd_v <= load && ((DEC_LA != 0) ? fqd_kvd[la_rd] : (ir[O_UNIT +: W_UNIT] == 2'd1 && ir[O_ME_WSRC]));
            wd_v <= load && ((DEC_LA != 0) ? fqd_wd[la_rd] : ((W_HBM != 0) && ir[O_UNIT +: W_UNIT] == 2'd1 && !ir[O_ME_WSRC]));
        end
    end
    assign kvd_wbase = me_wbase; assign kvd_ts = me_ts; assign kvd_ks = me_ks; assign kvd_js = me_js;
    assign kvd_wcs = me_wcs; assign kvd_split = me_split;
    assign kvd_jsh = me_jsh; assign kvd_tiles = me_tiles; assign kvd_k = me_k; assign kvd_nout = me_nout;
    assign kvd_kindk = me_kindk; assign kvd_pos = pos_r;
    assign wd_wbase = me_wbase; assign wd_tiles = me_tiles; assign wd_k = me_k;
    assign wd_sbase = (INT8_WEIGHT != 0 && INT8_SCALE_WCS_BASE != 0) ? me_wcs : me_wbase;
    assign wd_nout = me_nout; // useful BF16 row scales to preload from HBM

    // The chunked weight program divides lm_head into bounded streams. Fold
    // each completed chunk's argmax before issuing the next one. The final
    // chunk remains in u_me and is included exactly once at END.
    function automatic [31:0] okey(input [31:0] v);
        okey = v[31] ? ~v : {1'b1, v[30:0]};
    endfunction
    reg run_any;
    reg [31:0] run_key,run_val;
    reg [NW-1:0] run_idx,last_row0;

    // ---- DEC_LA_AMQ (tools/qwen_rom_core_issue_fallback_w12.py): the engine's argmax result (am_idx / am_val /
    // am_any, unit registers) is registered at the core boundary; the lm_head chunk fold and the END fold read the
    // registered copy one edge later (the fold's NEXT fields are captured with its trigger), and done / next_token /
    // next_val are written one edge after fin.  Values identical; +1 cycle per core program END only.
    reg [NW-1:0] amq_idx; reg [31:0] amq_val; reg amq_any;
    reg amf_v, amf_amc; reg [NW-1:0] amf_row0;
    always @(posedge clk) begin amq_idx <= am_idx; amq_val <= am_val; amq_any <= am_any; end
    always @(posedge clk or negedge rst_n_i)
        if (!rst_n_i) amf_v <= 1'b0;
        else amf_v <= (DEC_LA_AMQ != 0) && la_me_go_am && me_amax;
    always @(posedge clk) begin amf_amc <= me_amc; amf_row0 <= me_row0; end
    wire [NW-1:0] amv_idx = (DEC_LA_AMQ != 0) ? amq_idx : am_idx;
    wire [31:0] amv_val = (DEC_LA_AMQ != 0) ? amq_val : am_val;
    wire amv_any = (DEC_LA_AMQ != 0) ? amq_any : am_any;
    wire am_trig = (DEC_LA_AMQ != 0) ? amf_v : (la_me_go_am && me_amax);
    wire am_trig_amc = (DEC_LA_AMQ != 0) ? amf_amc : me_amc;
    wire [NW-1:0] am_trig_row0 = (DEC_LA_AMQ != 0) ? amf_row0 : me_row0;
    wire la_am_gt;
    ot_qwen_core_key_gt u_la_am_gt (.a(okey(amv_val)), .b(run_key), .gt(la_am_gt));
    wire am_wins = amv_any && (!run_any || ((DEC_LA != 0) ? la_am_gt : (okey(amv_val) > run_key)));
    wire [NW-1:0] fin_idx = am_wins ? amv_idx + last_row0 : run_idx;
    wire [31:0] fin_val = am_wins ? amv_val : run_val;
    always @(posedge clk or negedge rst_n_i) begin
        if (!rst_n_i) begin run_any<=1'b0; last_row0<=0; end
        else if (start_i && st==S_IDLE) begin run_any<=1'b0; last_row0<=0; end
        else if (am_trig) begin
            last_row0<=am_trig_row0;
            if (!am_trig_amc) run_any<=1'b0;
            else if (am_wins) run_any<=1'b1;
        end
    end

    // the running max's data registers: their own enable (DEC_LA_ISSUE_FB >= 3 drops the start_i / reset terms, which
    // never coincide with a fold trigger)
    always @(posedge clk)
        if (am_trig && am_trig_amc && am_wins && (DEC_LA_ISSUE_FB >= 3 || (rst_n_i && !(start_i && st == S_IDLE)))) begin
            run_key<=okey(amv_val); run_idx<=amv_idx+last_row0; run_val<=amv_val;
        end
    always @(posedge clk)
        if (((DEC_LA_AMQ != 0) ? fin_d : fin) && (DEC_LA_ISSUE_FB >= 3 || rst_n_i)) next_val <= fin_val;
    // DYN offsets derived once per token_i.
    always @(posedge clk) if (st == S_DYN) begin
        dyn[0] <= 0;
        dyn[1] <= tok_r * HID;
        dyn[2] <= pos_r * HALF;
        dyn[3] <= (pos_r >> LW) * (HD * W) + (pos_r & (W - 1));
        dyn[4] <= pos_r * HD;
        dyn[5] <= pos_r + 1;
        dyn[6] <= dyn_tiles_zero;                 // rounds of G position tiles (split 0)
        dyn[7] <= 0;
    end
    // VPOS: the eight per-position tables, same expressions at pos_i + o
    integer vpo;
    always @(posedge clk) if (VPOS != 0 && st == S_DYN) begin
        for (vpo = 0; vpo < 8; vpo = vpo + 1) begin
            dynp[vpo*8+0] <= 0;
            dynp[vpo*8+1] <= tok_r * HID;
            dynp[vpo*8+2] <= (pos_r + vpo[NW-1:0]) * HALF;
            dynp[vpo*8+3] <= ((pos_r + vpo[NW-1:0]) >> LW) * (HD * W) + ((pos_r + vpo[NW-1:0]) & (W - 1));
            dynp[vpo*8+4] <= (pos_r + vpo[NW-1:0]) * HD;
            dynp[vpo*8+5] <= pos_r + vpo[NW-1:0] + 1;
            dynp[vpo*8+6] <= dynp_tiles_zero_f[vpo*NW +: NW];
            dynp[vpo*8+7] <= 0;
        end
    end
    `define DYNS(sel) ((VPOS != 0) ? dynp[{vp_off, sel}] : dyn[sel])


    // ---- DEC_LA (tools/qwen_rom_core_dec_emit_w12.py): predecode at push, pipelined registered tables ----
    function automatic integer la_tz(input integer value);
        integer n;
        begin
            n = 0;
            while ((value & 1) == 0 && value > 0) begin value = value >> 1; n = n + 1; end
            la_tz = n;
        end
    endfunction
    localparam integer LA_WT = la_tz(W), LA_GT = la_tz(G), LA_ODD = G >> la_tz(G);
    localparam integer LA_NO = (VPOS != 0) ? 8 : 1;         // position offsets
    localparam integer LA_SW = NW + 2;                       // rounds operand: shifted position + ODD
    localparam integer LA_H = LA_SW / 2 - 3;                 // divider split (low part: remainder + LA_H bits)
    // stage 1 (E1): pos_r + o and, for every (o, split), ((pos_r + o) >> (WT + GT - split)) + ODD
    //   (rounds = that / ODD), both through kept prefix adders
    // stage 2 (E2): high-half quotient and remainder; the other DYN entries
    // stage 3 (E3): rounds (0 for an invalid split).  The first program word reaches prog_q_i at E3 and is
    //   registered (pend1) at E4, when every table entry is settled.
    reg [NW-1:0]    la_po [0:LA_NO-1];
    reg [LA_SW-1:0] la_sh [0:LA_NO*16-1];
    reg [AW-1:0]    la_tokh;
    reg [LA_SW-1:0] la_qh [0:LA_NO*16-1];
    // E2 remainder < ODD, packed above H low bits: at most ODD*2**H-1.
    // Preserve original SW truncation for other parameters. E1/E2/E3 unchanged.
    localparam integer LA_LO_W = (DEC_LA_BOUND != 0 && LA_ODD > 0 && LA_H > 0)
        ? ((LA_H + $clog2(LA_ODD) < LA_SW) ? LA_H + $clog2(LA_ODD) : LA_SW) : LA_SW;
    reg [LA_LO_W-1:0] la_lo [0:LA_NO*16-1];
    reg [AW-1:0]    la_tab [0:LA_NO*8-1];
    reg [NW-1:0]    la_rt [0:LA_NO*16-1];
    wire [15:0]  la_inv;
    wire [LA_NO*NW-1:0] la_po_n;            // packed: Yosys 0.68 asserts on an unpacked array bound to output ports
    wire [LA_NO*16*LA_SW-1:0] la_sh_n;
    genvar lap, las;
    generate for (las = 0; las < 16; las = las + 1) begin : g_la_inv
        assign la_inv[las] = (W != (1 << LA_WT)) || las > LA_GT || las > LA_WT + LA_GT;
    end endgenerate
    generate for (lap = 0; lap < LA_NO; lap = lap + 1) begin : g_la_po
        ot_hdc_ksadd_k #(.W(NW)) u_po (.a(pos_r), .b(lap), .cin(1'b0), .s(la_po_n[lap*NW +: NW]), .cout());
        for (las = 0; las < 16; las = las + 1) begin : g_s
            if (las > LA_GT || las > LA_WT + LA_GT) begin : g_inv
                assign la_sh_n[(lap*16+las)*LA_SW +: LA_SW] = {LA_SW{1'b0}};
            end else begin : g_ok
                ot_hdc_ksadd_k #(.W(LA_SW)) u_sh (.a({2'b00, (la_po_n[lap*NW +: NW] >> (LA_WT + LA_GT - las))}),
                                                 .b(LA_ODD), .cin(1'b0), .s(la_sh_n[(lap*16+las)*LA_SW +: LA_SW]), .cout());
            end
        end
    end endgenerate
    integer lo, ls;
    always @(posedge clk) if (DEC_LA != 0) begin
        la_tokh <= tok_r * HID;
        for (lo = 0; lo < LA_NO; lo = lo + 1) begin
            la_po[lo] <= la_po_n[lo*NW +: NW];
            for (ls = 0; ls < 16; ls = ls + 1)
                la_sh[lo*16+ls] <= la_sh_n[(lo*16+ls)*LA_SW +: LA_SW];
        end
        for (lo = 0; lo < LA_NO; lo = lo + 1) begin
            for (ls = 0; ls < 16; ls = ls + 1) begin
                la_qh[lo*16+ls] <= ((la_sh[lo*16+ls] >> LA_H) / LA_ODD) << LA_H;
                la_lo[lo*16+ls] <= (((la_sh[lo*16+ls] >> LA_H) % LA_ODD) << LA_H) | (la_sh[lo*16+ls] & ((1 << LA_H) - 1));
            end
            la_tab[lo*8+0] <= 0;
            la_tab[lo*8+1] <= la_tokh;
            la_tab[lo*8+2] <= la_po[lo] * HALF;
            la_tab[lo*8+3] <= (la_po[lo] >> LW) * (HD * W) + (la_po[lo] & (W - 1));
            la_tab[lo*8+4] <= la_po[lo] * HD;
            la_tab[lo*8+5] <= la_po[lo] + 1;
            la_tab[lo*8+6] <= 0;                                   // read from la_rt (split 0)
            la_tab[lo*8+7] <= 0;
        end
        for (lo = 0; lo < LA_NO * 16; lo = lo + 1)
            la_rt[lo] <= la_inv[lo % 16] ? {NW{1'b0}} : (la_qh[lo] | (la_lo[lo] / LA_ODD));
    end
    // the program word is staged one cycle (pq_r): the data fields of an entry are written one edge after its
    // push, which is no later than its LOAD edge, and they are read only after LOAD (from la_nx).  The table
    // lookups the word needs (its split rounds, its DYN values) are registered with it at pend1.
    reg [INSTR_BITS-1:0] pq_r;
    reg [2:0]     la_wr_r;
    reg           pq_v;
    reg  [7:0]    la_we;
    integer       lw;
    wire [2:0]    pg_off = (VPOS != 0) ? prog_q_i[900 +: 3] : 3'd0;
    wire [6:0]    pg_rti = ((VPOS != 0) ? {pg_off, 4'd0} : 7'd0) + prog_q_i[O_ME_SPLIT +: 4];
    reg  [NW-1:0] pq_split_rounds;
    always @(posedge clk) if (DEC_LA != 0) begin
        pq_v <= pend1; la_wr_r <= la_wr;
        la_we <= pend1 ? (8'd1 << la_wr) : 8'd0;     // one-hot write strobes of the staged word's slot
        if (pend1) begin
            pq_r <= prog_q_i;
            pq_split_rounds <= la_rt[pg_rti];
        end
    end
    integer lq, lk;
    reg  [AW-1:0] pq_dyn_A_D;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_A_D <= (prog_q_i[O_A_D +: W_A_D] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q_i[O_A_D +: W_A_D]];
    reg  [AW-1:0] pq_dyn_B_D;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_B_D <= (prog_q_i[O_B_D +: W_B_D] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q_i[O_B_D +: W_B_D]];
    reg  [AW-1:0] pq_dyn_C_D;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_C_D <= (prog_q_i[O_C_D +: W_C_D] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q_i[O_C_D +: W_C_D]];
    reg  [AW-1:0] pq_dyn_D_D;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_D_D <= (prog_q_i[O_D_D +: W_D_D] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q_i[O_D_D +: W_D_D]];
    reg  [AW-1:0] pq_dyn_ME_D_K;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_ME_D_K <= (prog_q_i[O_ME_D_K +: W_ME_D_K] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q_i[O_ME_D_K +: W_ME_D_K]];
    reg  [AW-1:0] pq_dyn_ME_D_NOUT;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_ME_D_NOUT <= (prog_q_i[O_ME_D_NOUT +: W_ME_D_NOUT] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q_i[O_ME_D_NOUT +: W_ME_D_NOUT]];
    reg  [AW-1:0] pq_dyn_ME_D_OBASE;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_ME_D_OBASE <= (prog_q_i[O_ME_D_OBASE +: W_ME_D_OBASE] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
